 13	import com.pousadamarealta.repository.RoomRepository;
 14	import com.pousadamarealta.service.PricingService;
 15	import com.pousadamarealta.service.ReportService;
 16	import com.pousadamarealta.service.ReservationService;
 17	import io.javalin.Javalin;
 18	import io.javalin.json.JavalinJackson;
 19	
 20	public class App {
 21	    public static void main(String[] args) {
 22	        String dbUrl = System.getenv().getOrDefault("DB_URL", "jdbc:postgresql://localhost:5432/pousada");
 23	        String dbUser = System.getenv().getOrDefault("DB_USER", "postgres");
 24	        String dbPassword = System.getenv().getOrDefault("DB_PASSWORD", "postgres");
 25	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "7070"));
 26	
 27	        DatabaseManager dbManager = new DatabaseManager(dbUrl, dbUser, dbPassword);
 28	        dbManager.initialize();
 29	
 30	        RoomRepository roomRepository = new RoomRepository(dbManager);
 31	        ReservationRepository reservationRepository = new ReservationRepository(dbManager);
 32	        MessageRepository messageRepository = new MessageRepository(dbManager);
 33	
 34	        PricingService pricingService = new PricingService();
 35	        ReservationService reservationService = new ReservationService(
 36	            reservationRepository, roomRepository, messageRepository, pricingService);
 37	        ReportService reportService = new ReportService(
 38	            reservationRepository, roomRepository, pricingService);
 39	
 40	        RoomHandler roomHandler = new RoomHandler(roomRepository);
 41	        ReservationHandler reservationHandler = new ReservationHandler(
 42	            reservationService, reservationRepository, roomRepository);
 43	        MessageHandler messageHandler = new MessageHandler(messageRepository);
 44	        ReportHandler reportHandler = new ReportHandler(reportService);
 45	
 46	        ObjectMapper objectMapper = new ObjectMapper();
 47	        objectMapper.registerModule(new JavaTimeModule());
 48	        objectMapper.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 49	
 50	        Javalin app = Javalin.create(config -> {
 51	            config.jsonMapper(new JavalinJackson(objectMapper, true));
 52	        }).start(port);
 53	
 54	        app.get("/rooms", roomHandler::getAllRooms);
 55	
 56	        app.post("/reservations", reservationHandler::createReservation);
 57	        app.get("/reservations/{id}", reservationHandler::getReservation);
 58	        app.post("/reservations/{id}/confirmation", reservationHandler::confirmReservation);
 59	        app.post("/reservations/{id}/cancellation", reservationHandler::cancelReservation);
 60	        app.post("/reservations/{id}/check-in", reservationHandler::checkIn);
 61	        app.post("/reservations/{id}/check-out", reservationHandler::checkOut);
 62	        app.get("/reservations/{id}/document", reservationHandler::getDocument);
 63	
 64	        app.get("/messages", messageHandler::getAllMessages);
 65	
 66	        app.get("/reports/occupancy", reportHandler::getOccupancyReport);
 67	        app.get("/reports/revenue", reportHandler::getRevenueReport);
 68	        app.get("/reports/tourism-tax", reportHandler::getTourismTaxReport);
 69	        app.get("/reports/rate-plans", reportHandler::getRatePlansReport);
 70	
 71	        System.out.println("Pousada Maré Alta reservation system running on port " + port);
 72	    }
 73	}
 74	package com.pousadamarealta.database;
 75	
 76	import java.sql.Connection;
 77	import java.sql.DriverManager;
 78	import java.sql.SQLException;
 79	import java.sql.Statement;
 80	
 81	public class DatabaseManager {
 82	    private final String url;
 83	    private final String user;
 84	    private final String password;
 85	
 86	    public DatabaseManager(String url, String user, String password) {
 87	        this.url = url;
 88	        this.user = user;
 89	        this.password = password;
 90	    }
 91	
 92	    public Connection getConnection() throws SQLException {
 93	        return DriverManager.getConnection(url, user, password);
 94	    }
 95	
 96	    public void initialize() {
 97	        try (Connection conn = getConnection();
 98	             Statement stmt = conn.createStatement()) {
 99	
100	            stmt.execute("""
101	                CREATE TABLE IF NOT EXISTS rooms (
102	                    number VARCHAR(10) PRIMARY KEY,
103	                    type VARCHAR(20) NOT NULL
104	                )
105	                """);
106	
107	            stmt.execute("""
108	                CREATE TABLE IF NOT EXISTS reservations (
109	                    id SERIAL PRIMARY KEY,
110	                    room_number VARCHAR(10) NOT NULL,
111	                    guest_name VARCHAR(255) NOT NULL,
112	                    guest_email VARCHAR(255) NOT NULL,
113	                    guest_cpf VARCHAR(14) NOT NULL,
114	                    check_in DATE NOT NULL,
115	                    check_out DATE NOT NULL,
116	                    guests INTEGER NOT NULL,
117	                    rate_plan VARCHAR(20) NOT NULL,
118	                    nights INTEGER NOT NULL,
119	                    subtotal DECIMAL(10, 2) NOT NULL,
120	                    discount DECIMAL(10, 2) NOT NULL,
121	                    total DECIMAL(10, 2) NOT NULL,
122	                    status VARCHAR(20) NOT NULL,
123	                    amount_paid DECIMAL(10, 2) NOT NULL,
124	                    refund DECIMAL(10, 2),
125	                    FOREIGN KEY (room_number) REFERENCES rooms(number)
126	                )
127	                """);
128	
129	            stmt.execute("""
130	                CREATE TABLE IF NOT EXISTS messages (
131	                    id SERIAL PRIMARY KEY,
132	                    channel VARCHAR(20) NOT NULL,
133	                    recipient VARCHAR(255) NOT NULL,
134	                    subject VARCHAR(500) NOT NULL,
135	                    body TEXT NOT NULL
136	                )
137	                """);
138	
139	            initializeRooms(conn);
140	
141	        } catch (SQLException e) {
142	            throw new RuntimeException("Failed to initialize database", e);
143	        }
144	    }
145	
146	    private void initializeRooms(Connection conn) throws SQLException {
147	        try (Statement stmt = conn.createStatement()) {
148	            stmt.execute("SELECT COUNT(*) FROM rooms");
149	            var rs = stmt.getResultSet();
150	            rs.next();
151	            if (rs.getInt(1) == 0) {
152	                stmt.execute("INSERT INTO rooms (number, type) VALUES ('101', 'STANDARD')");
153	                stmt.execute("INSERT INTO rooms (number, type) VALUES ('102', 'STANDARD')");
154	                stmt.execute("INSERT INTO rooms (number, type) VALUES ('201', 'DELUXE')");
155	                stmt.execute("INSERT INTO rooms (number, type) VALUES ('202', 'DELUXE')");
156	                stmt.execute("INSERT INTO rooms (number, type) VALUES ('301', 'SUITE')");
157	            }
158	        }
159	    }
160	}
