177	public class ReservationHandler {
178	    private final ReservationService reservationService;
179	    private final ReservationRepository reservationRepository;
180	    private final RoomRepository roomRepository;
181	
182	    public ReservationHandler(ReservationService reservationService,
183	                            ReservationRepository reservationRepository,
184	                            RoomRepository roomRepository) {
185	        this.reservationService = reservationService;
186	        this.reservationRepository = reservationRepository;
187	        this.roomRepository = roomRepository;
188	    }
189	
190	    public void createReservation(Context ctx) {
191	        try {
192	            CreateReservationRequest request = ctx.bodyAsClass(CreateReservationRequest.class);
193	
194	            if (request.getRoomNumber() == null || request.getGuestName() == null ||
195	                request.getGuestEmail() == null || request.getGuestCpf() == null ||
196	                request.getCheckIn() == null || request.getCheckOut() == null ||
197	                request.getGuests() == null || request.getRatePlan() == null) {
198	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Missing required fields"));
199	                return;
200	            }
201	
202	            LocalDate checkIn;
203	            LocalDate checkOut;
204	            try {
205	                checkIn = LocalDate.parse(request.getCheckIn());
206	                checkOut = LocalDate.parse(request.getCheckOut());
207	            } catch (DateTimeParseException e) {
208	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid date format"));
209	                return;
210	            }
211	
212	            RatePlan ratePlan;
213	            try {
214	                ratePlan = RatePlan.valueOf(request.getRatePlan());
215	            } catch (IllegalArgumentException e) {
216	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid rate plan"));
217	                return;
218	            }
219	
220	            Reservation reservation = reservationService.createReservation(
221	                request.getRoomNumber(),
222	                request.getGuestName(),
223	                request.getGuestEmail(),
224	                request.getGuestCpf(),
225	                checkIn,
226	                checkOut,
227	                request.getGuests(),
228	                ratePlan
229	            );
230	
231	            ctx.status(201).json(toResponseMap(reservation));
232	
233	        } catch (ReservationService.RoomNotFoundException e) {
234	            ctx.status(404).json(new ErrorResponse("ROOM_NOT_FOUND", "Room not found"));
235	        } catch (ReservationService.InvalidRequestException e) {
236	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
237	        } catch (ReservationService.CapacityExceededException e) {
238	            ctx.status(422).json(new ErrorResponse("CAPACITY_EXCEEDED", "Number of guests exceeds room capacity"));
239	        } catch (ReservationService.RoomUnavailableException e) {
240	            ctx.status(409).json(new ErrorResponse("ROOM_UNAVAILABLE", "Room is not available for the selected dates"));
241	        } catch (Exception e) {
242	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid request"));
243	        }
244	    }
245	
246	    public void getReservation(Context ctx) {
247	        try {
248	            Long id = Long.parseLong(ctx.pathParam("id"));
249	            Reservation reservation = reservationRepository.findById(id)
250	                .orElseThrow(() -> new ReservationService.ReservationNotFoundException());
251	
252	            ctx.json(toResponseMap(reservation));
253	
254	        } catch (NumberFormatException e) {
255	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
256	        } catch (ReservationService.ReservationNotFoundException e) {
257	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
258	        }
259	    }
260	
261	    public void confirmReservation(Context ctx) {
262	        try {
263	            Long id = Long.parseLong(ctx.pathParam("id"));
264	            Reservation reservation = reservationService.confirmReservation(id);
265	            ctx.json(toResponseMap(reservation));
266	
267	        } catch (NumberFormatException e) {
268	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
269	        } catch (ReservationService.ReservationNotFoundException e) {
270	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
271	        } catch (ReservationService.OperationNotAllowedException e) {
272	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Operation not allowed for current reservation status"));
273	        }
274	    }
275	
276	    public void cancelReservation(Context ctx) {
277	        try {
278	            Long id = Long.parseLong(ctx.pathParam("id"));
279	            Reservation reservation = reservationService.cancelReservation(id);
280	            ctx.json(toResponseMap(reservation));
281	
282	        } catch (NumberFormatException e) {
283	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
284	        } catch (ReservationService.ReservationNotFoundException e) {
285	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
286	        } catch (ReservationService.OperationNotAllowedException e) {
287	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Operation not allowed for current reservation status"));
288	        }
289	    }
