306	    public void checkOut(Context ctx) {
307	        try {
308	            Long id = Long.parseLong(ctx.pathParam("id"));
309	            Reservation reservation = reservationService.checkOut(id);
310	            String receipt = reservationService.generateReceipt(reservation);
311	
312	            var room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
313	
314	            Map<String, Object> response = new HashMap<>();
315	            response.put("title", "Comprovante de reserva");
316	            response.put("reservationId", reservation.getId());
317	            response.put("guestName", reservation.getGuestName());
