322	            response.put("checkOut", reservation.getCheckOut().toString());
323	            response.put("nights", reservation.getNights());
324	            response.put("subtotal", reservation.getSubtotal().doubleValue());
325	            response.put("discount", reservation.getDiscount().doubleValue());
326	            response.put("total", reservation.getTotal().doubleValue());
327	
328	            ctx.json(response);
329	
330	        } catch (NumberFormatException e) {
331	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
332	        } catch (ReservationService.ReservationNotFoundException e) {
333	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
334	        } catch (ReservationService.OperationNotAllowedException e) {
335	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Operation not allowed for current reservation status"));
336	        }
337	    }
