340	        try {
341	            Long id = Long.parseLong(ctx.pathParam("id"));
342	            Reservation reservation = reservationRepository.findById(id)
343	                .orElseThrow(() -> new ReservationService.ReservationNotFoundException());
344	
345	            var room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
