349	            response.put("reservationId", reservation.getId());
350	            response.put("guestName", reservation.getGuestName());
351	            response.put("guestCpf", reservation.getGuestCpf());
352	            response.put("roomNumber", reservation.getRoomNumber());
353	            response.put("roomType", room.getType().name());
354	            response.put("checkIn", reservation.getCheckIn().toString());
355	            response.put("checkOut", reservation.getCheckOut().toString());
356	            response.put("nights", reservation.getNights());
357	            response.put("subtotal", reservation.getSubtotal().doubleValue());
358	            response.put("discount", reservation.getDiscount().doubleValue());
359	            response.put("total", reservation.getTotal().doubleValue());
360	
361	            ctx.json(response);
362	
363	        } catch (NumberFormatException e) {
364	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
365	        } catch (ReservationService.ReservationNotFoundException e) {
366	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
367	        } catch (ReservationService.OperationNotAllowedException e) {
368	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Cannot generate document for pending reservation"));
369	        }
370	    }
371	
372	    private Map<String, Object> toResponseMap(Reservation reservation) {
373	        Map<String, Object> map = new HashMap<>();
374	        map.put("id", reservation.getId());
375	        map.put("roomNumber", reservation.getRoomNumber());
376	        map.put("guestName", reservation.getGuestName());
377	        map.put("guestEmail", reservation.getGuestEmail());
378	        map.put("guestCpf", reservation.getGuestCpf());
379	        map.put("checkIn", reservation.getCheckIn().toString());
380	        map.put("checkOut", reservation.getCheckOut().toString());
381	        map.put("guests", reservation.getGuests());
382	        map.put("ratePlan", reservation.getRatePlan().name());
383	        map.put("nights", reservation.getNights());
384	        map.put("subtotal", reservation.getSubtotal().doubleValue());
385	        map.put("discount", reservation.getDiscount().doubleValue());
386	        map.put("total", reservation.getTotal().doubleValue());
387	        map.put("status", reservation.getStatus().name());
388	        map.put("amountPaid", reservation.getAmountPaid().doubleValue());
389	        map.put("refund", reservation.getRefund() != null ? reservation.getRefund().doubleValue() : null);
390	        return map;
391	    }
392	}
