285	    public Reservation confirmReservation(Long id) {
286	        Reservation reservation = reservationRepository.findById(id)
287	            .orElseThrow(() -> new ReservationNotFoundException());
288	
289	        if (reservation.getStatus() != ReservationStatus.PENDING) {
290	            throw new OperationNotAllowedException();
291	        }
292	
293	        reservation.setStatus(ReservationStatus.CONFIRMED);
294	        reservation.setAmountPaid(reservation.getTotal());
295	        reservationRepository.save(reservation);
296	
297	        sendConfirmationEmail(reservation);
298	
299	        return reservation;
300	    }
