320	        Reservation reservation = reservationRepository.findById(id)
321	            .orElseThrow(() -> new ReservationNotFoundException());
322	
323	        if (reservation.getStatus() != ReservationStatus.PENDING &&
324	            reservation.getStatus() != ReservationStatus.CONFIRMED) {
325	            throw new OperationNotAllowedException();
326	        }
327	
328	        reservation.setStatus(ReservationStatus.CANCELLED);
329	
330	        BigDecimal refundAmount = BigDecimal.ZERO;
331	        if (reservation.getRatePlan() == RatePlan.STANDARD) {
332	            refundAmount = reservation.getAmountPaid();
333	        }
334	        reservation.setRefund(refundAmount);
335	
336	        return reservationRepository.save(reservation);
337	    }
