339	    public Reservation checkIn(Long id) {
340	        Reservation reservation = reservationRepository.findById(id)
341	            .orElseThrow(() -> new ReservationNotFoundException());
342	
343	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
344	            throw new OperationNotAllowedException();
345	        }
346	
347	        reservation.setStatus(ReservationStatus.CHECKED_IN);
348	        return reservationRepository.save(reservation);
349	    }
