351	    public Reservation checkOut(Long id) {
352	        Reservation reservation = reservationRepository.findById(id)
353	            .orElseThrow(() -> new ReservationNotFoundException());
354	
355	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
356	            throw new OperationNotAllowedException();
357	        }
358	
359	        reservation.setStatus(ReservationStatus.CHECKED_OUT);
360	        return reservationRepository.save(reservation);
361	    }
