363	    public String generateReceipt(Reservation reservation) {
364	        if (reservation.getStatus() == ReservationStatus.PENDING) {
365	            throw new OperationNotAllowedException();
366	        }
367	
368	        Room room = roomRepository.findByNumber(reservation.getRoomNumber())
369	            .orElseThrow(() -> new RoomNotFoundException());
370	
371	        StringBuilder receipt = new StringBuilder();
372	        receipt.append(String.format("Comprovante de reserva nº %d\n", reservation.getId()));
373	        receipt.append(String.format("Hóspede: %s (CPF %s)\n",
374	            reservation.getGuestName(), formatCpf(reservation.getGuestCpf())));
375	        receipt.append(String.format("Quarto: %s (%s)\n",
376	            reservation.getRoomNumber(), room.getType().name()));
377	        receipt.append(String.format("Entrada: %s | Saída: %s | %d %s\n",
378	            formatDate(reservation.getCheckIn()),
379	            formatDate(reservation.getCheckOut()),
380	            reservation.getNights(),
381	            reservation.getNights() == 1 ? "diária" : "diárias"));
382	        receipt.append(String.format("Diárias: %s\n", formatMoney(reservation.getSubtotal())));
383	
384	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
385	            receipt.append(String.format("Desconto: %s\n", formatMoney(reservation.getDiscount())));
386	        }
387	
388	        receipt.append(String.format("Total: %s", formatMoney(reservation.getTotal())));
389	
390	        return receipt.toString();
391	    }
392	
393	    private String formatCpf(String cpf) {
394	        if (cpf.length() == 11) {
395	            return String.format("%s.%s.%s-%s",
396	                cpf.substring(0, 3),
397	                cpf.substring(3, 6),
398	                cpf.substring(6, 9),
399	                cpf.substring(9, 11));
400	        }
401	        return cpf;
402	    }
403	
404	    private String formatDate(LocalDate date) {
405	        return String.format("%02d/%02d/%04d",
406	            date.getDayOfMonth(),
407	            date.getMonthValue(),
408	            date.getYear());
409	    }
410	
411	    private String formatMoney(BigDecimal amount) {
412	        String formatted = String.format("%,.2f", amount);
413	        formatted = formatted.replace(',', 'X').replace('.', ',').replace('X', '.');
414	        return "R$ " + formatted;
415	    }
