440	import java.math.BigDecimal;
441	import java.math.RoundingMode;
442	import java.time.LocalDate;
443	import java.time.Month;
444	
445	public class PricingService {
446	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
447	
448	    public BigDecimal calculateNightPrice(BigDecimal baseRate, LocalDate date) {
449	        if (isHighSeason(date)) {
450	            return roundBankers(baseRate.multiply(HIGH_SEASON_MULTIPLIER));
451	        }
452	        return baseRate;
453	    }
454	
455	    public boolean isHighSeason(LocalDate date) {
456	        int month = date.getMonthValue();
457	        int day = date.getDayOfMonth();
458	
459	        if (month == Month.DECEMBER.getValue() && day >= 15) {
460	            return true;
461	        }
462	
463	        if (month == Month.JANUARY.getValue() || month == Month.FEBRUARY.getValue()) {
464	            return true;
465	        }
466	
467	        if (month == Month.JULY.getValue()) {
468	            return true;
469	        }
470	
471	        return false;
472	    }
473	
474	    public BigDecimal roundBankers(BigDecimal value) {
475	        return value.setScale(2, RoundingMode.HALF_EVEN);
476	    }
