165	            int count = planReservations.size();
166	
167	            BigDecimal amount = planReservations.stream()
168	                .map(r -> {
169	                    BigDecimal net = r.getAmountPaid();
170	                    if (r.getRefund() != null) {
171	                        net = net.subtract(r.getRefund());
172	                    }
173	                    return net;
174	                })
175	                .reduce(BigDecimal.ZERO, BigDecimal::add);
176	
177	            csv.append(plan.name()).append(",");
178	            csv.append(count).append(",");
179	            csv.append(formatCsvNumber(amount)).append("\n");
180	
181	            totalAmount = totalAmount.add(amount);
182	            totalCount += count;
183	        }
184	
185	        csv.append("total,").append(totalCount).append(",").append(formatCsvNumber(totalAmount));
186	
187	        return csv.toString();
188	    }
189	
190	    private String formatCsvNumber(BigDecimal value) {
191	        return value.setScale(2, java.math.RoundingMode.HALF_EVEN).toPlainString();
192	    }
193	}
