201	import java.math.BigDecimal;
202	import java.time.LocalDate;
203	import java.time.temporal.ChronoUnit;
204	
205	public class ReservationService {
206	    private final ReservationRepository reservationRepository;
207	    private final RoomRepository roomRepository;
208	    private final MessageRepository messageRepository;
209	    private final PricingService pricingService;
210	
211	    public ReservationService(ReservationRepository reservationRepository,
212	                            RoomRepository roomRepository,
213	                            MessageRepository messageRepository,
214	                            PricingService pricingService) {
215	        this.reservationRepository = reservationRepository;
216	        this.roomRepository = roomRepository;
217	        this.messageRepository = messageRepository;
218	        this.pricingService = pricingService;
219	    }
220	
221	    public Reservation createReservation(String roomNumber, String guestName, String guestEmail,
222	                                       String guestCpf, LocalDate checkIn, LocalDate checkOut,
223	                                       int guests, RatePlan ratePlan) {
224	        Room room = roomRepository.findByNumber(roomNumber)
225	            .orElseThrow(() -> new RoomNotFoundException());
226	
227	        if (guests < 1) {
228	            throw new InvalidRequestException("At least one guest is required");
229	        }
230	
231	        if (guests > room.getCapacity()) {
232	            throw new CapacityExceededException();
233	        }
234	
235	        if (!checkOut.isAfter(checkIn)) {
236	            throw new InvalidRequestException("Check-out must be after check-in");
237	        }
238	
239	        var conflicts = reservationRepository.findConflicting(roomNumber, checkIn, checkOut, null);
240	        if (!conflicts.isEmpty()) {
241	            throw new RoomUnavailableException();
242	        }
243	
244	        Reservation reservation = new Reservation();
245	        reservation.setRoomNumber(roomNumber);
246	        reservation.setGuestName(guestName);
247	        reservation.setGuestEmail(guestEmail);
248	        reservation.setGuestCpf(guestCpf);
249	        reservation.setCheckIn(checkIn);
250	        reservation.setCheckOut(checkOut);
251	        reservation.setGuests(guests);
252	        reservation.setRatePlan(ratePlan);
253	
254	        calculatePricing(reservation, room);
255	
256	        return reservationRepository.save(reservation);
257	    }
258	
259	    private void calculatePricing(Reservation reservation, Room room) {
260	        int nights = (int) ChronoUnit.DAYS.between(reservation.getCheckIn(), reservation.getCheckOut());
261	        reservation.setNights(nights);
262	
263	        BigDecimal subtotal = BigDecimal.ZERO;
264	        LocalDate currentDate = reservation.getCheckIn();
265	
266	        for (int i = 0; i < nights; i++) {
267	            BigDecimal nightPrice = pricingService.calculateNightPrice(room.getNightlyRate(), currentDate);
268	            subtotal = subtotal.add(nightPrice);
269	            currentDate = currentDate.plusDays(1);
270	        }
271	
272	        subtotal = pricingService.roundBankers(subtotal);
273	        reservation.setSubtotal(subtotal);
274	
275	        BigDecimal discount = BigDecimal.ZERO;
276	        if (reservation.getRatePlan() == RatePlan.NON_REFUNDABLE) {
277	            discount = pricingService.roundBankers(subtotal.multiply(reservation.getRatePlan().getDiscountRate()));
278	        }
279	        reservation.setDiscount(discount);
280	
281	        BigDecimal total = pricingService.roundBankers(subtotal.subtract(discount));
282	        reservation.setTotal(total);
283	    }
284	
285	    public Reservation confirmReservation(Long id) {
286	        Reservation reservation = reservationRepository.findById(id)
287	            .orElseThrow(() -> new ReservationNotFoundException());
288	
289	        if (reservation.getStatus() != ReservationStatus.PENDING) {
290	            throw new OperationNotAllowedException();
291	        }
292	
293	        reservation.setStatus(ReservationStatus.CONFIRMED);
294	        reservation.setAmountPaid(reservation.getTotal());
295	        reservationRepository.save(reservation);
296	
297	        sendConfirmationEmail(reservation);
298	
299	        return reservation;
300	    }
