302	    private void sendConfirmationEmail(Reservation reservation) {
303	        String receipt = generateReceipt(reservation);
304	        String subject = "Reserva confirmada - Pousada Maré Alta";
305	        String body = String.format("""
306	            Olá, %s!
307	
308	            Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:
309	
310	            %s
311	
312	            A entrada é a partir das 14h, e a saída, até as 12h.
313	            Até breve!""", reservation.getGuestName(), receipt);
314	
315	        Message message = new Message(MessageChannel.EMAIL, reservation.getGuestEmail(), subject, body);
316	        messageRepository.save(message);
317	    }
318	
319	    public Reservation cancelReservation(Long id) {
320	        Reservation reservation = reservationRepository.findById(id)
321	            .orElseThrow(() -> new ReservationNotFoundException());
322	
323	        if (reservation.getStatus() != ReservationStatus.PENDING &&
324	            reservation.getStatus() != ReservationStatus.CONFIRMED) {
325	            throw new OperationNotAllowedException();
326	        }
327	
328	        reservation.setStatus(ReservationStatus.CANCELLED);
329	
330	        BigDecimal refundAmount = BigDecimal.ZERO;
331	        if (reservation.getRatePlan() == RatePlan.STANDARD) {
332	            refundAmount = reservation.getAmountPaid();
333	        }
334	        reservation.setRefund(refundAmount);
335	
336	        return reservationRepository.save(reservation);
337	    }
338	
339	    public Reservation checkIn(Long id) {
340	        Reservation reservation = reservationRepository.findById(id)
341	            .orElseThrow(() -> new ReservationNotFoundException());
342	
343	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
344	            throw new OperationNotAllowedException();
345	        }
346	
347	        reservation.setStatus(ReservationStatus.CHECKED_IN);
348	        return reservationRepository.save(reservation);
349	    }
350	
351	    public Reservation checkOut(Long id) {
352	        Reservation reservation = reservationRepository.findById(id)
353	            .orElseThrow(() -> new ReservationNotFoundException());
354	
355	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
356	            throw new OperationNotAllowedException();
357	        }
358	
359	        reservation.setStatus(ReservationStatus.CHECKED_OUT);
360	        return reservationRepository.save(reservation);
361	    }
362	
363	    public String generateReceipt(Reservation reservation) {
364	        if (reservation.getStatus() == ReservationStatus.PENDING) {
365	            throw new OperationNotAllowedException();
366	        }
367	
368	        Room room = roomRepository.findByNumber(reservation.getRoomNumber())
369	            .orElseThrow(() -> new RoomNotFoundException());
370	
371	        StringBuilder receipt = new StringBuilder();
372	        receipt.append(String.format("Comprovante de reserva nº %d\n", reservation.getId()));
373	        receipt.append(String.format("Hóspede: %s (CPF %s)\n",
374	            reservation.getGuestName(), formatCpf(reservation.getGuestCpf())));
375	        receipt.append(String.format("Quarto: %s (%s)\n",
376	            reservation.getRoomNumber(), room.getType().name()));
377	        receipt.append(String.format("Entrada: %s | Saída: %s | %d %s\n",
378	            formatDate(reservation.getCheckIn()),
379	            formatDate(reservation.getCheckOut()),
380	            reservation.getNights(),
381	            reservation.getNights() == 1 ? "diária" : "diárias"));
382	        receipt.append(String.format("Diárias: %s\n", formatMoney(reservation.getSubtotal())));
383	
384	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
385	            receipt.append(String.format("Desconto: %s\n", formatMoney(reservation.getDiscount())));
386	        }
387	
388	        receipt.append(String.format("Total: %s", formatMoney(reservation.getTotal())));
389	
390	        return receipt.toString();
391	    }
392	
393	    private String formatCpf(String cpf) {
394	        if (cpf.length() == 11) {
395	            return String.format("%s.%s.%s-%s",
396	                cpf.substring(0, 3),
397	                cpf.substring(3, 6),
398	                cpf.substring(6, 9),
399	                cpf.substring(9, 11));
400	        }
401	        return cpf;
402	    }
403	
404	    private String formatDate(LocalDate date) {
405	        return String.format("%02d/%02d/%04d",
406	            date.getDayOfMonth(),
407	            date.getMonthValue(),
408	            date.getYear());
409	    }
410	
411	    private String formatMoney(BigDecimal amount) {
412	        String formatted = String.format("%,.2f", amount);
413	        formatted = formatted.replace(',', 'X').replace('.', ',').replace('X', '.');
414	        return "R$ " + formatted;
415	    }
416	
417	    public static class RoomNotFoundException extends RuntimeException {
418	    }
419	
420	    public static class ReservationNotFoundException extends RuntimeException {
421	    }
422	
423	    public static class InvalidRequestException extends RuntimeException {
424	        public InvalidRequestException(String message) {
425	            super(message);
426	        }
427	    }
428	
429	    public static class CapacityExceededException extends RuntimeException {
430	    }
431	
432	    public static class RoomUnavailableException extends RuntimeException {
433	    }
434	
435	    public static class OperationNotAllowedException extends RuntimeException {
436	    }
437	}
438	package com.pousadamarealta.service;
439	
440	import java.math.BigDecimal;
441	import java.math.RoundingMode;
442	import java.time.LocalDate;
443	import java.time.Month;
444	
445	public class PricingService {
446	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
447	
448	    public BigDecimal calculateNightPrice(BigDecimal baseRate, LocalDate date) {
449	        if (isHighSeason(date)) {
450	            return roundBankers(baseRate.multiply(HIGH_SEASON_MULTIPLIER));
451	        }
452	        return baseRate;
453	    }
454	
455	    public boolean isHighSeason(LocalDate date) {
456	        int month = date.getMonthValue();
457	        int day = date.getDayOfMonth();
458	
459	        if (month == Month.DECEMBER.getValue() && day >= 15) {
460	            return true;
461	        }
462	
463	        if (month == Month.JANUARY.getValue() || month == Month.FEBRUARY.getValue()) {
464	            return true;
465	        }
466	
467	        if (month == Month.JULY.getValue()) {
468	            return true;
469	        }
470	
471	        return false;
472	    }
473	
474	    public BigDecimal roundBankers(BigDecimal value) {
475	        return value.setScale(2, RoundingMode.HALF_EVEN);
476	    }
477	}

