 77	                room_number = ?, guest_name = ?, guest_email = ?, guest_cpf = ?,
 78	                check_in = ?, check_out = ?, guests = ?, rate_plan = ?,
 79	                nights = ?, subtotal = ?, discount = ?, total = ?,
 80	                status = ?, amount_paid = ?, refund = ?
