210	    public List<Reservation> findByCheckInMonth(String month) {
211	        String sql = """
212	            SELECT id, room_number, guest_name, guest_email, guest_cpf,
213	                check_in, check_out, guests, rate_plan, nights, subtotal, discount, total,
214	                status, amount_paid, refund
215	            FROM reservations
216	            WHERE TO_CHAR(check_in, 'YYYY-MM') = ?
217	            ORDER BY check_in, id
218	            """;
219	
220	        List<Reservation> reservations = new ArrayList<>();
221	        try (var conn = dbManager.getConnection();
222	             var stmt = conn.prepareStatement(sql)) {
223	
224	            stmt.setString(1, month);
225	
226	            var rs = stmt.executeQuery();
227	
228	            while (rs.next()) {
229	                reservations.add(mapReservation(rs));
