237	    private Reservation mapReservation(java.sql.ResultSet rs) throws SQLException {
238	        Reservation reservation = new Reservation();
239	        reservation.setId(rs.getLong("id"));
240	        reservation.setRoomNumber(rs.getString("room_number"));
241	        reservation.setGuestName(rs.getString("guest_name"));
242	        reservation.setGuestEmail(rs.getString("guest_email"));
243	        reservation.setGuestCpf(rs.getString("guest_cpf"));
244	        reservation.setCheckIn(rs.getDate("check_in").toLocalDate());
245	        reservation.setCheckOut(rs.getDate("check_out").toLocalDate());
246	        reservation.setGuests(rs.getInt("guests"));
247	        reservation.setRatePlan(RatePlan.valueOf(rs.getString("rate_plan")));
248	        reservation.setNights(rs.getInt("nights"));
249	        reservation.setSubtotal(rs.getBigDecimal("subtotal"));
250	        reservation.setDiscount(rs.getBigDecimal("discount"));
251	        reservation.setTotal(rs.getBigDecimal("total"));
252	        reservation.setStatus(ReservationStatus.valueOf(rs.getString("status")));
253	        reservation.setAmountPaid(rs.getBigDecimal("amount_paid"));
254	        var refund = rs.getBigDecimal("refund");
255	        if (refund != null) {
256	            reservation.setRefund(refund);
257	        }
258	        return reservation;
259	    }
